#!/usr/bin/env bash
#
# Validates the subject of a commit message against Conventional Commits and the length limit.
# Usage: scripts/check-commit-msg.sh <file with the commit message>

set -euo pipefail

file="${1:?usage: check-commit-msg.sh <commit-message-file>}"

# First line that is not a comment added by Git
subject="$(grep -v '^#' "$file" | head -n 1 || true)"

# Messages generated by Git itself
if [[ "$subject" =~ ^(Merge|Revert|fixup!|squash!|amend!)\  ]]; then
    exit 0
fi

pattern='^(feat|fix|chore|refactor|test|docs|ci)(\([a-z0-9._/-]+\))?!?: .+'
if [[ "$subject" =~ $pattern ]] && ((${#subject} <= 72)); then
    exit 0
fi

cat >&2 <<EOF
Commit message does not follow Conventional Commits or is longer than 72 characters:
  ${subject:-<empty>}

Expected: <type>(<optional scope>): <description>
Types:    feat, fix, chore, refactor, test, docs, ci
Example:  fix: keep the pnpm completion after pnpm nx
EOF
exit 1
